/**
 * Quiz question engine — generic question format served from `quiz_items`
 * (supabase/quiz-engine.sql), generated by the backend cron.
 *
 * Mirrors narsil-museum-backend/src/quiz/types.ts — keep the two in sync.
 * The app draws one renderer per answer type (components/quiz/), so a new
 * backend style that reuses these answer types needs no app release.
 */

export const ENGINE_ANSWER_TYPES = [
  "single",
  "multi",
  "binary",
  "order",
  "match",
  "numeric",
  "text",
] as const;

export type AnswerType = (typeof ENGINE_ANSWER_TYPES)[number];

/** Zoom window: scale by `scale` around transform-origin (`x`, `y`), 0–1. */
export interface Crop {
  x: number;
  y: number;
  scale: number;
}

export interface ItemOption {
  id: string;
  label?: string;
  image_url?: string;
  artwork_id?: string;
  accent?: string;
  crop?: Crop;
  flip?: boolean;
  /** Revealed under the option once answered. */
  note?: string;
}

export interface ItemTarget {
  id: string;
  label: string;
}

export type RevealEffect = "none" | "zoom" | "blur" | "tiles";

export interface ItemMedia {
  label: string;
  image_url?: string;
  artwork_id?: string;
  accent?: string;
  reveal?: RevealEffect;
  reveal_seconds?: number;
  crop?: Crop;
  flip?: boolean;
  hole?: Crop;
  caption?: string;
  compare?: { image_url: string; artwork_id: string; accent?: string; label: string };
  clues?: string[];
  image_after_answer?: boolean;
  select_count?: number;
  targets?: ItemTarget[];
  letters?: string[];
  suggestions?: string[];
  slider?: { min: number; max: number; step: number; unit?: string };
  options_as?: "text" | "image" | "tiles";
  columns?: number;
}

export interface ChoiceAnswer {
  correct: string[];
}
export interface OrderAnswer {
  order: string[];
}
export interface MatchAnswer {
  pairs: Record<string, string>;
}
export interface NumericAnswer {
  value: number;
  full_within: number;
  zero_beyond: number;
  display: string;
}
export interface TextAnswer {
  accept: string[];
  display: string;
}

export type ItemAnswer =
  | ChoiceAnswer
  | OrderAnswer
  | MatchAnswer
  | NumericAnswer
  | TextAnswer;

export interface QuizItem {
  id: string;
  style: string;
  answer_type: AnswerType;
  prompt: string;
  media: ItemMedia;
  options: ItemOption[];
  answer: ItemAnswer;
  explain?: string | null;
  difficulty?: string;
  artwork_ids: string[];
}

export type PlayerResponse =
  | { kind: "choice"; ids: string[] }
  | { kind: "order"; ids: string[] }
  | { kind: "match"; pairs: Record<string, string> }
  | { kind: "numeric"; value: number }
  | { kind: "text"; value: string };

export interface ScoreResult {
  correct: boolean;
  fraction: number;
}
